export function graphql(source: "fragment WorkerFields on Worker {\n  id\n  name\n  version\n  kinds\n  connectedAt\n  lastSeenAt\n}\n\nfragment WorkerJobFields on WorkerJob {\n  id\n  kind\n  status\n  workerId\n  priority\n  progress\n  message\n  error\n  createdAt\n  startedAt\n  finishedAt\n}\n\nquery Workers {\n  workers {\n    ...WorkerFields\n  }\n  workerJobs(limit: 50) {\n    ...WorkerJobFields\n  }\n}\n\nmutation CancelWorkerJob($id: String!) {\n  cancelWorkerJob(id: $id) {\n    ...WorkerJobFields\n  }\n}\n\nsubscription WorkerJobEvents {\n  readEvents {\n    __typename\n    ... on WorkerJobChanged {\n      id\n      kind\n      status\n      workerId\n      progress\n      message\n      error\n    }\n  }\n}"): (typeof documents)["fragment WorkerFields on Worker {\n  id\n  name\n  version\n  kinds\n  connectedAt\n  lastSeenAt\n}\n\nfragment WorkerJobFields on WorkerJob {\n  id\n  kind\n  status\n  workerId\n  priority\n  progress\n  message\n  error\n  createdAt\n  startedAt\n  finishedAt\n}\n\nquery Workers {\n  workers {\n    ...WorkerFields\n  }\n  workerJobs(limit: 50) {\n    ...WorkerJobFields\n  }\n}\n\nmutation CancelWorkerJob($id: String!) {\n  cancelWorkerJob(id: $id) {\n    ...WorkerJobFields\n  }\n}\n\nsubscription WorkerJobEvents {\n  readEvents {\n    __typename\n    ... on WorkerJobChanged {\n      id\n      kind\n      status\n      workerId\n      progress\n      message\n      error\n    }\n  }\n}"];

export function graphql(source: string) {
  return (documents as any)[source] ?? {};
}

export type DocumentType<TDocumentNode extends DocumentNode<any, any>> = TDocumentNode extends DocumentNode<  infer TType,  any>  ? TType  : never;